import React, { useState } from 'react';
import ExperienceCard from '../../components/ExperienceCard/ExperienceCard';
import usePortfolioData from '../../hooks/usePortfolioData';
import styles from './Experience.module.css';
import interactions from '../../components/PortfolioInteractions/Interactions.module.css';

export default function Experience({ initialCompanyId, initialContributionIndex = 0, onExplore }) {
  const { experience, projects } = usePortfolioData();
  const [expandedId, setExpandedId] = useState(initialCompanyId || null);
  const caseStudies = projects.filter(project => project.source === 'Résumé');
  return (
    <div className={`${styles.container} ${interactions.scope}`}>
      <header className={styles.headerContainer}><h1 className={styles.headerTitle}>Experience</h1></header>
      <p className={interactions.pageIntro}>Select a company to explore my contributions, the technologies behind them, and their outcomes.</p>
      <div className={styles.experienceGrid}>
        {experience.map(job => <ExperienceCard key={job.id} job={job} caseStudies={caseStudies} initialContributionIndex={job.id === initialCompanyId ? initialContributionIndex : 0} expanded={expandedId === job.id} onToggle={() => setExpandedId(value => value === job.id ? null : job.id)} onExplore={onExplore} />)}
      </div>
    </div>
  );
}
